package in.gov.nic.apar.config;

import org.springframework.scheduling.annotation.*; import org.springframework.stereotype.Component; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@Component @EnableScheduling @ConditionalOnProperty(name="apar.reminders-enabled",havingValue="true") public class ReminderScheduler { private final JdbcTemplate db; public ReminderScheduler(JdbcTemplate d){db=d;} @Scheduled(cron="0 0 9 * * *",zone="Asia/Kolkata") public void remind(){try{db.update("insert into tran.notification(recipient_employee_id,type,title,message) select s.employee_id,'APAR_REMINDER','APAR deadline reminder','Your APAR submission is pending. Please submit before the assessment deadline.' from tran.employee_acr_status s join tran.acr_cycle c on c.id=s.cycle_id where c.is_open=true and s.requested=true and s.status in ('PENDING','NEEDS_RESUBMISSION') and c.due_date between current_date and current_date+7 and not exists(select 1 from tran.notification n where n.recipient_employee_id=s.employee_id and n.type='APAR_REMINDER' and n.created_at::date=current_date)");}catch(Exception ignored){}} }
